<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Device\Infrastructure\Driver\Rest;

use DateTimeImmutable;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Oidc\Client\Domain\ClientData;
use Civi\Lughauth\Features\Oidc\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\Oidc\Device\Application\DeviceAuthorizationService;
use Civi\Lughauth\Features\Oidc\Device\Domain\Exception\DeviceAuthorizationException;
use OpenApi\Attributes as OA;

class DeviceAuthorizationController
{
    public function __construct(
        private readonly Context $context,
        private readonly ClientStoreGateway $clients,
        private readonly DeviceAuthorizationService $deviceAuth
    ) {
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/device',
        summary: 'Device Authorization Request (RFC 8628)',
        description: 'Initiates the OAuth 2.0 Device Authorization Grant flow. Returns device_code and user_code for the device to display.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            content: new OA\MediaType(
                mediaType: 'application/x-www-form-urlencoded',
                schema: new OA\Schema(properties: [
                    new OA\Property(property: 'client_id', type: 'string'),
                    new OA\Property(property: 'scope', type: 'string'),
                    new OA\Property(property: 'audience', type: 'string'),
                ])
            )
        ),
        responses: [
            new OA\Response(
                response: 200,
                description: 'Device authorization response',
                content: new OA\JsonContent(properties: [
                    new OA\Property(property: 'device_code', type: 'string'),
                    new OA\Property(property: 'user_code', type: 'string', example: 'ABCD-1234'),
                    new OA\Property(property: 'verification_uri', type: 'string'),
                    new OA\Property(property: 'verification_uri_complete', type: 'string'),
                    new OA\Property(property: 'expires_in', type: 'integer'),
                    new OA\Property(property: 'interval', type: 'integer'),
                ])
            ),
            new OA\Response(response: 400, description: 'Invalid request'),
            new OA\Response(response: 401, description: 'Invalid client'),
        ]
    )]
    public function post(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $params = (array) ($request->getParsedBody() ?? []);
        try {
            $client = $this->resolveClient($params);
            if (false === array_search(DeviceAuthorizationService::grantType(), $client->grants)) {
                throw DeviceAuthorizationException::invalidClient();
            }
            $scope = (string) ($params['scope'] ?? '');
            $audiences = $this->normalizeAudiences($params['audience'] ?? null);
            $authorization = $this->deviceAuth->createAuthorization($tenant, $client, $scope, $audiences);

            $baseUrl = rtrim($this->context->getBaseUrl(), '/');
            $verification = $baseUrl . '/oauth/openid/' . $tenant . '/device/verify';
            $now = new DateTimeImmutable();
            $payload = [
                'device_code' => $authorization->deviceCode,
                'user_code' => $authorization->userCode,
                'verification_uri' => $verification,
                'verification_uri_complete' => $verification . '?user_code=' . urlencode($authorization->userCode),
                'expires_in' => $authorization->expiresIn($now),
                'interval' => $authorization->interval
            ];
            if ($scope !== '') {
                $payload['scope'] = $scope;
            }
            $encoded = json_encode($payload);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withHeader('Content-Type', 'application/json');
        } catch (DeviceAuthorizationException $ex) {
            $payload = [
                'error' => $ex->error(),
                'error_description' => $ex->getMessage()
            ];
            $encoded = json_encode($payload);
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response
                ->withStatus($ex->statusCode())
                ->withHeader('Content-Type', 'application/json');
        }
    }

    private function resolveClient(array $params): ClientData
    {
        if (isset($_SERVER['PHP_AUTH_USER']) && isset($_SERVER['PHP_AUTH_PW'])) {
            $client = $this->clients->clientData($_SERVER['PHP_AUTH_USER'], $_SERVER['PHP_AUTH_PW']);
            if (!$client) {
                throw DeviceAuthorizationException::invalidClient();
            }
            return $client;
        }

        $clientId = (string) ($params['client_id'] ?? '');
        if ($clientId === '') {
            throw DeviceAuthorizationException::invalidRequest('client_id is required');
        }
        $client = $this->clients->preValidatedClient($clientId);
        if (!$client) {
            throw DeviceAuthorizationException::invalidClient();
        }
        return $client;
    }

    /**
     * @return string[]
     */
    private function normalizeAudiences(mixed $audience): array
    {
        if (is_array($audience)) {
            $raw = $audience;
        } elseif (is_string($audience)) {
            $raw = $audience === '' ? [] : explode(',', $audience);
        } else {
            $raw = [];
        }

        $items = array_map(static fn ($value): string => trim((string) $value), $raw);
        $items = array_filter($items, static fn (string $value): bool => $value !== '');

        return array_values(array_unique($items));
    }
}
